-- Geo Follow-Up: when a bid reaches Won or Lost with no Date Quoted, fill it with that day (covers bids that never went through Geo Bids' Quoted column). Safe to run more than once.
update wf_spaces s set rules = coalesce(s.rules,'[]'::jsonb) || jsonb_build_array(jsonb_build_object('id','rdqwon','kind','fill','status',(select st->>'name' from jsonb_array_elements(s.statuses) st where lower(st->>'name')='won' limit 1),'field','cf:f_quoted','value','@today','blank',true), jsonb_build_object('id','rdqlost','kind','fill','status',(select st->>'name' from jsonb_array_elements(s.statuses) st where lower(st->>'name')='lost' limit 1),'field','cf:f_quoted','value','@today','blank',true)) where s.key='GF' and s.division_id in (select id::text from divisions where lower(name)='geo') and not exists (select 1 from jsonb_array_elements(coalesce(s.rules,'[]'::jsonb)) r where r->>'kind'='fill' and r->>'field'='cf:f_quoted') returning name, jsonb_array_length(rules) as automations;
